class Youtube{constructor(url,options={}){this.id=this.idFromUrl(url);this.width="";this.height="";this.ratio="16x9";this.autoplay=false;this.related=false;this.fullscreen=true;this.hd=false;if(typeof options==="object")this.set(options);this.url=this.setSrcUrl();this.placeholder=this.setPlaceholderUrl()}set(options){let instance=this;for(var key in options){if(options.hasOwnProperty(key))instance[key]=options[key]}}idFromUrl(url){let match=url.match(/^.*(youtu\.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/);return match&&match[2].length===11?match[2]:false}setSrcUrl(){return"https://www.youtube.com/embed/"+this.id+"?rel="+(this.related?"1":"0")+"&autoplay="+(this.autoplay?"1":"0")}setPlaceholderUrl(){return{jpeg:"https://i.ytimg.com/vi/"+this.id+"/",webp:"https://i.ytimg.com/vi_webp/"+this.id+"/"}}createIframe(width=750,height=315){return'<iframe src="'+this.url+'" width="'+width+'" height="'+height+'" frameborder="0" allowfullscreen>&nbsp;</iframe>'}compiledHTML(){let params={videoId:this.id,height:this.height,width:this.width,playerVars:{autoplay:this.autoplay?1:0,rel:this.related?1:0,fs:this.fullscreen?1:0,hd:this.hd?1:0}};let bsRatio=this.ratio.replace("by","x");let html='<div class="ratio ratio-'+bsRatio+' mb-3">';html+='<picture class="ytb-video-preview" data-ytb=\''+JSON.stringify(params)+"'>";html+='<source type="image/webp" sizes="(min-width: 640px) 1280px" srcset="'+this.placeholder.webp+'maxresdefault.webp 1280w">';html+='<source type="image/webp" sizes="(min-width: 480px) 640px" srcset="'+this.placeholder.webp+'hqdefault.webp 640w">';html+='<source type="image/webp" sizes="(min-width: 320px) 480px" srcset="'+this.placeholder.webp+'mqdefault.webp 480w">';html+='<source type="image/webp" sizes="(min-width: 120px) 320px" srcset="'+this.placeholder.webp+'sddefault.webp 320w">';html+='<source type="image/webp" sizes="120px" srcset="'+this.placeholder.webp+'default.webp 120w">';html+='<source type="image/jpeg" sizes="(min-width: 640px) 1280px" srcset="'+this.placeholder.jpeg+'maxresdefault.jpg 1280w">';html+='<source type="image/jpeg" sizes="(min-width: 480px) 640px" srcset="'+this.placeholder.jpeg+'hqdefault.jpg 640w">';html+='<source type="image/jpeg" sizes="(min-width: 320px) 480px" srcset="'+this.placeholder.jpeg+'mqdefault.jpg 480w">';html+='<source type="image/jpeg" sizes="(min-width: 120px) 320px" srcset="'+this.placeholder.jpeg+'sddefault.jpg 320w">';html+='<source type="image/jpeg" sizes="120px" srcset="'+this.placeholder.jpeg+'default.jpg 120w">';html+='<img src="'+this.placeholder.jpeg+'default.jpg" srcset="'+this.placeholder.jpeg+"maxresdefault.webp 1280w, "+this.placeholder.jpeg+"maxresdefault.webp 640w, "+this.placeholder.jpeg+"maxresdefault.webp 480w, "+this.placeholder.jpeg+"maxresdefault.webp 320w, "+this.placeholder.jpeg+'maxresdefault.webp 120w" sizes="(min-width: 640px) 1280px, (min-width: 480px) 640px, (min-width: 320px) 480px, (min-width: 120px) 320px, 120px" alt="Accept embed video cookie to display the video" loading="lazy" class="img-fluid w-100 h-100 object-fit-cover lazyload" data-ytb=\''+JSON.stringify(params)+"' />";html+="</picture>";html+="</div><p></p>";return html}}